INSERT INTO hardware_catalog.categories(name) SELECT DISTINCT category FROM incoming_hardware_catalog ON CONFLICT(name) DO NOTHING;
INSERT INTO hardware_catalog.subcategories(category_id,name) SELECT DISTINCT c.id,i.subcategory FROM incoming_hardware_catalog i JOIN hardware_catalog.categories c ON c.name=i.category ON CONFLICT(category_id,name) DO NOTHING;
INSERT INTO hardware_catalog.products AS existing (subcategory_id,name,description,active) SELECT s.id,i.product_name,MAX(i.description),BOOL_OR(i.active) FROM incoming_hardware_catalog i JOIN hardware_catalog.categories c ON c.name=i.category JOIN hardware_catalog.subcategories s ON s.category_id=c.id AND s.name=i.subcategory GROUP BY s.id,i.product_name ON CONFLICT(subcategory_id,name) DO UPDATE SET description=COALESCE(existing.description,EXCLUDED.description), active=existing.active OR EXCLUDED.active;
INSERT INTO hardware_catalog.product_variants AS existing (product_id,sku,brand,size_specification,unit,description,active) SELECT p.id,i.sku,i.brand,i.size_specification,i.unit,i.description,i.active FROM incoming_hardware_catalog i JOIN hardware_catalog.categories c ON c.name=i.category JOIN hardware_catalog.subcategories s ON s.category_id=c.id AND s.name=i.subcategory JOIN hardware_catalog.products p ON p.subcategory_id=s.id AND p.name=i.product_name ON CONFLICT(sku) DO UPDATE SET product_id=EXCLUDED.product_id, brand=EXCLUDED.brand, size_specification=EXCLUDED.size_specification, unit=EXCLUDED.unit, description=COALESCE(EXCLUDED.description,existing.description), active=EXCLUDED.active, updated_at=NOW();
